function OrdersLedger() {
  const [orders, setOrders] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [query, setQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [sortDir, setSortDir] = useState('desc');
  const [formOpen, setFormOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [invalidFields, setInvalidFields] = useState([]);
  const [shakeKey, setShakeKey] = useState(0);
  const [toast, setToast] = useState(null);
  const [highlightId, setHighlightId] = useState(null);
  const [viewingOrder, setViewingOrder] = useState(null);

  const [appStage, setAppStage] = useState('splash'); // splash | login | app
  const [idle, setIdle] = useState(false);
  const [authMode, setAuthMode] = useState('viewer'); // viewer | admin
  const [authForm, setAuthForm] = useState({ username: '', password: '' });
  const [authError, setAuthError] = useState('');
  const [authSaving, setAuthSaving] = useState(false);
  const [authShakeKey, setAuthShakeKey] = useState(0);
  const [currentRole, setCurrentRole] = useState(null); // 'admin' | 'viewer'
  const [permissions, setPermissions] = useState(DEFAULT_PERMISSIONS);
  const [adminUsername, setAdminUsername] = useState('');
  const [adminOpen, setAdminOpen] = useState(false);
  const [reportsOpen, setReportsOpen] = useState(false);
  const [viewers, setViewers] = useState([]);

  useEffect(() => {
    (async () => {
      try {
        const list = await window.ordersAPI.list();
        setOrders(list || []);
      } catch (e) {
        console.error('load orders error:', e);
      } finally {
        setLoaded(true);
      }
    })();
  }, []);

  useEffect(() => {
    const t = setTimeout(() => setAppStage('login'), SPLASH_MIN_MS);
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    if (appStage === 'splash') return;
    let timer;
    const resetTimer = () => {
      setIdle(false);
      clearTimeout(timer);
      timer = setTimeout(() => setIdle(true), IDLE_TIMEOUT_MS);
    };
    const events = ['mousemove', 'mousedown', 'touchstart', 'touchmove', 'keydown', 'wheel'];
    events.forEach(ev => window.addEventListener(ev, resetTimer, { passive: true }));
    resetTimer();
    return () => {
      clearTimeout(timer);
      events.forEach(ev => window.removeEventListener(ev, resetTimer));
    };
  }, [appStage]);

  async function handleAuthSubmit(e) {
    e.preventDefault();
    const missing = [];
    if (!authForm.username.trim()) missing.push('username');
    if (!authForm.password) missing.push('password');
    if (missing.length) {
      setAuthError('رجاءً عبّي اسم المستخدم وكلمة السر');
      setAuthShakeKey(k => k + 1);
      return;
    }
    setAuthSaving(true);
    setAuthError('');
    const uname = authForm.username.trim();

    if (authMode === 'admin') {
      const enteredHash = await sha256(authForm.password);
      const storedHash = await getAdminPasswordHash();
      if (uname === ADMIN_USERNAME && enteredHash === storedHash) {
        setAppStage('app');
        setCurrentRole('admin');
        setPermissions(FULL_PERMISSIONS);
        setAdminUsername(uname);
        setToast('أهلاً بك يا مسؤول النظام');
        setAuthForm({ username: '', password: '' });
        setAuthSaving(false);
        setTimeout(() => setToast(null), 2600);
      } else {
        setAuthError('اسم المستخدم أو كلمة السر غير صحيحة');
        setAuthShakeKey(k => k + 1);
        setAuthSaving(false);
      }
      return;
    }

    // تسجيل دخول المشاهدين: نتحقق من حسابات المشاهدة التي أنشأها مسؤول النظام
    try {
      let viewersList = [];
      if (window.storage && typeof window.storage.get === 'function') {
        try {
          const res = await withTimeout(window.storage.get(VIEWERS_KEY, false), 4000);
          if (res && res.value) viewersList = JSON.parse(res.value).map(normalizeViewer);
        } catch (e) {
          // لا توجد حسابات مشاهدة بعد
        }
      }

      const viewerMatch = viewersList.find(v => v.username === uname && v.password === authForm.password);
      if (viewerMatch) {
        setAppStage('app');
        setCurrentRole('viewer');
        setPermissions(viewerMatch.permissions || DEFAULT_PERMISSIONS);
        setToast('أهلاً بك');
        setAuthForm({ username: '', password: '' });
        setTimeout(() => setToast(null), 2600);
      } else {
        setAuthError('اسم المستخدم أو كلمة السر غير صحيحة');
        setAuthShakeKey(k => k + 1);
      }
    } catch (err) {
      console.error('auth error:', err);
      if (err && err.message === 'storage-timeout') {
        setAuthError('تعذّر التحقق من الحساب لأن الاتصال بطيء، حاول مرة أخرى');
      } else {
        setAuthError('صار خطأ غير متوقع، حاول مرة أخرى');
      }
      setAuthShakeKey(k => k + 1);
    } finally {
      setAuthSaving(false);
    }
  }

  function handleLogout() {
    setAppStage('login');
    setAuthMode('viewer');
    setAuthForm({ username: '', password: '' });
    setAuthError('');
    setCurrentRole(null);
    setPermissions(DEFAULT_PERMISSIONS);
    setAdminUsername('');
    setAdminOpen(false);
    setViewers([]);
  }

  async function loadViewers() {
    try {
      if (!window.storage || typeof window.storage.get !== 'function') return;
      const res = await withTimeout(window.storage.get(VIEWERS_KEY, false), 4000);
      if (res && res.value) setViewers(JSON.parse(res.value).map(normalizeViewer));
    } catch (e) {
      // لا توجد حسابات مشاهدة بعد
    }
  }

  async function addViewerAccount(username, password, perms) {
    const entry = { id: uid(), username, password, permissions: { ...DEFAULT_PERMISSIONS, ...perms }, createdAt: Date.now() };
    const next = [...viewers, entry];
    setViewers(next);
    if (window.storage && typeof window.storage.set === 'function') {
      await withTimeout(window.storage.set(VIEWERS_KEY, JSON.stringify(next), false), 4000);
    }
    return entry;
  }

  async function deleteViewerAccount(id) {
    const next = viewers.filter(v => v.id !== id);
    setViewers(next);
    try {
      if (window.storage && typeof window.storage.set === 'function') {
        await withTimeout(window.storage.set(VIEWERS_KEY, JSON.stringify(next), false), 4000);
      }
    } catch (e) {
      console.error('delete viewer error:', e);
      setToast('تنبيه: تعذّر حذف الحساب بشكل دائم من التخزين');
      setTimeout(() => setToast(null), 4000);
    }
  }

  async function updateViewerPermissions(id, perms) {
    const next = viewers.map(v => (v.id === id ? { ...v, permissions: { ...v.permissions, ...perms } } : v));
    setViewers(next);
    try {
      if (window.storage && typeof window.storage.set === 'function') {
        await withTimeout(window.storage.set(VIEWERS_KEY, JSON.stringify(next), false), 4000);
      }
    } catch (e) {
      console.error('update permissions error:', e);
      setToast('تنبيه: تعذّر حفظ تغيير الصلاحيات بشكل دائم');
      setTimeout(() => setToast(null), 4000);
    }
  }

  async function changeViewerPassword(id, newPassword) {
    const next = viewers.map(v => (v.id === id ? { ...v, password: newPassword } : v));
    setViewers(next);
    if (window.storage && typeof window.storage.set === 'function') {
      await withTimeout(window.storage.set(VIEWERS_KEY, JSON.stringify(next), false), 4000);
    }
  }

  async function changeAdminPassword(newPassword) {
    const hash = await sha256(newPassword);
    if (window.storage && typeof window.storage.set === 'function') {
      await withTimeout(window.storage.set(ADMIN_PASSWORD_KEY, hash, false), 4000);
    }
  }

  async function saveOrderToStorage(order) {
    await window.ordersAPI.save(order);
  }

  async function deleteOrderFromStorage(id) {
    await window.ordersAPI.remove(id);
  }

  function openNew() {
    setForm(emptyForm);
    setEditingId(null);
    setError('');
    setInvalidFields([]);
    setFormOpen(true);
  }

  function openEdit(order) {
    setForm({
      orderNumber: order.orderNumber,
      department: order.department,
      category: order.category || '',
      requestedBy: order.requestedBy || '',
      createdPer: order.createdPer || '',
      supplier: order.supplier || '',
      orderDate: order.orderDate,
      poIssued: order.poIssued,
      poDate: order.poDate || '',
      poNumber: order.poNumber || '',
      receivedStatus: getReceivedStatus(order),
      receivedQty: order.receivedQty || '',
      totalQty: order.totalQty || '',
      notes: order.notes || '',
      attachments: order.attachments || [],
    });
    setEditingId(order.id);
    setError('');
    setInvalidFields([]);
    setFormOpen(true);
    setViewingOrder(null);
  }

  function openView(order) {
    setViewingOrder(order);
  }

  async function handleSubmit(e) {
    e.preventDefault();
    const missing = [];
    if (!form.orderNumber.trim()) missing.push('orderNumber');
    if (!form.department.trim()) missing.push('department');
    if (!form.category) missing.push('category');
    if (!form.requestedBy.trim()) missing.push('requestedBy');
    if (!form.createdPer.trim()) missing.push('createdPer');
    if (!form.orderDate) missing.push('orderDate');
    if (missing.length) {
      setInvalidFields(missing);
      setError('رجاءً عبّي الحقول المطلوبة المحدّدة بالأسفل');
      setShakeKey(k => k + 1);
      return;
    }
    setInvalidFields([]);
    setSaving(true);
    setError('');
    try {
      let next;
      let newId = editingId;
      let orderObj;
      if (editingId) {
        const existing = orders.find(o => o.id === editingId) || {};
        orderObj = { ...existing, ...form, id: editingId };
        next = orders.map(o => (o.id === editingId ? orderObj : o));
      } else {
        newId = uid();
        orderObj = { id: newId, ...form, createdAt: Date.now() };
        next = [...orders, orderObj];
      }
      setOrders(next);
      setFormOpen(false);
      setForm(emptyForm);
      const wasEditing = !!editingId;
      setEditingId(null);

      // تأكد أن الطلب المُضاف/المعدَّل يظهر فورًا حتى لو كانت الفلاتر تخفيه
      setQuery('');
      setStatusFilter('all');
      setCategoryFilter('all');

      setToast(wasEditing ? 'تم حفظ التعديلات' : 'تمت إضافة الطلب بنجاح');
      setHighlightId(newId);
      setTimeout(() => setToast(null), 2600);
      setTimeout(() => setHighlightId(null), 2200);

      saveOrderToStorage(orderObj).catch(err => {
        console.error('save order error:', err);
        setToast('تنبيه: تعذّر حفظ الطلب بشكل دائم، حاول مرة أخرى لاحقًا');
        setTimeout(() => setToast(null), 4000);
      });
    } catch (err) {
      console.error('handleSubmit error:', err);
      setError('صار خطأ غير متوقع أثناء الحفظ، حاول مرة أخرى');
    } finally {
      setSaving(false);
    }
  }

  async function handleDelete(id) {
    setOrders(prev => prev.filter(o => o.id !== id));
    setViewingOrder(v => (v && v.id === id ? null : v));
    deleteOrderFromStorage(id).catch(err => {
      console.error('delete order error:', err);
      setToast('تنبيه: تعذّر حذف الطلب من التخزين الدائم');
      setTimeout(() => setToast(null), 4000);
    });
  }

  const filtered = useMemo(() => {
    let list = [...orders];
    const q = query.trim().toLowerCase();
    if (q) {
      list = list.filter(
        o =>
          o.orderNumber.toLowerCase().includes(q) ||
          o.department.toLowerCase().includes(q) ||
          (o.poNumber || '').toLowerCase().includes(q) ||
          (o.supplier || '').toLowerCase().includes(q)
      );
    }
    if (statusFilter === 'issued') list = list.filter(o => o.poIssued);
    if (statusFilter === 'pending') list = list.filter(o => !o.poIssued);
    if (categoryFilter !== 'all') list = list.filter(o => o.category === categoryFilter);
    list.sort((a, b) => {
      const da = new Date(a.orderDate).getTime() || 0;
      const db = new Date(b.orderDate).getTime() || 0;
      if (da !== db) return sortDir === 'desc' ? db - da : da - db;

      // نفس التاريخ: رتّب تلقائيًا برقم الطلب (الأكبر فوق عند "الأحدث أولاً")
      const na = parseFloat(String(a.orderNumber).replace(/[^\d.-]/g, ''));
      const nb = parseFloat(String(b.orderNumber).replace(/[^\d.-]/g, ''));
      if (!isNaN(na) && !isNaN(nb) && na !== nb) {
        return sortDir === 'desc' ? nb - na : na - nb;
      }
      return sortDir === 'desc'
        ? String(b.orderNumber).localeCompare(String(a.orderNumber))
        : String(a.orderNumber).localeCompare(String(b.orderNumber));
    });
    return list;
  }, [orders, query, statusFilter, categoryFilter, sortDir]);

  const counts = useMemo(
    () => ({
      total: orders.length,
      issued: orders.filter(o => o.poIssued).length,
      pending: orders.filter(o => !o.poIssued).length,
    }),
    [orders]
  );

  return (
    <div dir="rtl" lang="ar" style={{ minHeight: '100vh', position: 'relative', fontFamily: "'Tajawal', sans-serif", color: TEXT }}>
      <div
        style={{
          position: 'fixed', inset: 0, zIndex: 0,
          backgroundImage: `url(${BG_IMAGE})`,
          backgroundSize: 'cover', backgroundPosition: 'center 35%',
        }}
      />
      <div
        style={{
          position: 'fixed', inset: 0, zIndex: 0,
          background: 'linear-gradient(180deg, rgba(4,8,14,0.5) 0%, rgba(4,8,14,0.72) 45%, rgba(4,8,14,0.92) 100%)',
        }}
      />

      <div style={{ position: 'relative', zIndex: 1 }}>
        <style>{`
          @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@600;700;800&family=Tajawal:wght@400;500;700&display=swap');

          html { color-scheme: dark; }
          select { color-scheme: dark; }
          option { background: #131A26; color: ${TEXT}; }

          .glass { backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px); }

          .stamp-issued {
            box-shadow: 0 0 0 1px rgba(87,182,255,0.35), 0 0 16px rgba(87,182,255,0.35);
          }
          .stamp-pending { box-shadow: 0 0 0 1px rgba(147,160,179,0.25); }

          input, select, textarea, .filter-pill {
            transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease, transform 0.15s ease;
          }
          input:focus, select:focus, textarea:focus, .filter-pill:focus-visible, button:focus-visible {
            outline: none;
            border-color: ${ACCENT} !important;
            box-shadow: 0 0 0 3px rgba(87,182,255,0.22);
          }
          .filter-pill:hover { background: rgba(255,255,255,0.10) !important; transform: translateY(-1px); }
          .filter-pill:active { transform: translateY(0) scale(0.98); }

          @keyframes formOpen {
            from { opacity: 0; transform: translateY(-8px) scaleY(0.97); }
            to { opacity: 1; transform: translateY(0) scaleY(1); }
          }
          .form-open { animation: formOpen 0.28s cubic-bezier(0.22, 1, 0.36, 1) both; transform-origin: top; }

          @keyframes rowIn {
            from { opacity: 0; transform: translateY(6px); }
            to { opacity: 1; transform: translateY(0); }
          }
          .row-in { animation: rowIn 0.32s ease both; }

          @keyframes introFromRight {
            from { opacity: 0; transform: translateX(36px); }
            to { opacity: 1; transform: translateX(0); }
          }
          @keyframes introFromLeft {
            from { opacity: 0; transform: translateX(-36px); }
            to { opacity: 1; transform: translateX(0); }
          }
          .intro-from-right { animation: introFromRight 0.6s cubic-bezier(0.22, 1, 0.36, 1) both; }
          .intro-from-left { animation: introFromLeft 0.6s cubic-bezier(0.22, 1, 0.36, 1) both; }

          @keyframes shakeField {
            10%, 90% { transform: translateX(-1px); }
            20%, 80% { transform: translateX(2px); }
            30%, 50%, 70% { transform: translateX(-4px); }
            40%, 60% { transform: translateX(4px); }
          }
          .field-shake { animation: shakeField 0.45s ease; }

          @keyframes toastIn {
            0% { opacity: 0; transform: translate(-50%, -14px); }
            12% { opacity: 1; transform: translate(-50%, 0); }
            88% { opacity: 1; transform: translate(-50%, 0); }
            100% { opacity: 0; transform: translate(-50%, -8px); }
          }
          .toast-in { animation: toastIn 2.6s cubic-bezier(0.22, 1, 0.36, 1) both; }

          @keyframes rowHighlight {
            0% { background-color: rgba(87,182,255,0.22); }
            100% { background-color: transparent; }
          }
          .row-highlight { animation: rowHighlight 2s ease; }

          @keyframes heroLine {
            0% { opacity: 0; transform: scaleX(0.3); }
            100% { opacity: 1; transform: scaleX(1); }
          }
          .hero-line { animation: heroLine 0.9s cubic-bezier(0.22, 1, 0.36, 1) both; transform-origin: center; }

          button { transition: transform 0.15s ease, opacity 0.15s ease, background-color 0.15s ease, box-shadow 0.15s ease; }
          button:active { transform: scale(0.96); }

          @keyframes splashTextIn {
            from { opacity: 0; transform: translateY(10px) scale(0.98); }
            to { opacity: 1; transform: translateY(0) scale(1); }
          }
          .splash-text { animation: splashTextIn 0.9s cubic-bezier(0.22, 1, 0.36, 1) both; }
          .splash-sub { animation: splashTextIn 0.9s cubic-bezier(0.22, 1, 0.36, 1) 0.25s both; }

          @keyframes charFromRight {
            from { opacity: 0; transform: translateX(70px); }
            to { opacity: 1; transform: translateX(0); }
          }
          @keyframes charFromLeft {
            from { opacity: 0; transform: translateX(-70px); }
            to { opacity: 1; transform: translateX(0); }
          }

          @keyframes splashFadeOut {
            from { opacity: 1; }
            to { opacity: 0; }
          }
          .splash-out { animation: splashFadeOut 0.6s ease both; }

          @keyframes appFadeIn {
            from { opacity: 0; }
            to { opacity: 1; }
          }
          .app-fade-in { animation: appFadeIn 0.5s ease both; }

          @keyframes overlayFadeIn {
            from { opacity: 0; }
            to { opacity: 1; }
          }
          .idle-overlay { animation: overlayFadeIn 0.8s ease both; }

          @keyframes verseIn {
            from { opacity: 0; transform: translateY(14px) scale(0.97); filter: blur(6px); }
            to { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
          }
          .verse-in { animation: verseIn 1s cubic-bezier(0.22, 1, 0.36, 1) both; }

          @media (prefers-reduced-motion: reduce) { * { animation: none !important; transition: none !important; } }
        `}</style>

        {appStage === 'splash' && <Splash />}

        {appStage === 'login' && (
          <AuthScreen
            authMode={authMode}
            setAuthMode={mode => {
              setAuthMode(mode);
              setAuthError('');
              setAuthForm({ username: '', password: '' });
            }}
            form={authForm}
            setForm={setAuthForm}
            onSubmit={handleAuthSubmit}
            saving={authSaving}
            error={authError}
            shakeKey={authShakeKey}
          />
        )}

        {appStage === 'app' && (
        <div className="app-fade-in">
        <header style={{ background: GLASS_STRONG, borderBottom: `1px solid ${GLASS_BORDER}` }} className="px-5 sm:px-8 py-6 glass">
          <div className="max-w-4xl mx-auto">
            <div className="flex items-center justify-between gap-4">
              <div className="flex items-center gap-3">
                <div style={{ background: ACCENT, color: ACCENT_TEXT_ON, boxShadow: '0 0 20px rgba(87,182,255,0.45)' }} className="w-11 h-11 rounded-full flex items-center justify-center shrink-0">
                  <FileStack size={22} />
                </div>
                <div>
                  <h1 style={{ fontFamily: "'Cairo', sans-serif", color: TEXT }} className="text-xl sm:text-2xl font-bold leading-tight">
                    سجل الطلبات
                  </h1>
                  <p style={{ color: TEXT_MUTED }} className="text-xs sm:text-sm">
                    تتبّع طلباتك وأوامر الشراء الصادرة
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                {currentRole === 'admin' && (
                  <button
                    onClick={() => {
                      setAdminOpen(true);
                      loadViewers();
                    }}
                    style={{ background: GLASS_SOFT, color: TEXT_MUTED, border: `1px solid ${GLASS_BORDER}` }}
                    className="flex items-center gap-1.5 font-bold text-sm px-3 py-2.5 rounded-full"
                    aria-label="لوحة الإدارة"
                  >
                    <Shield size={16} />
                    <span className="hidden sm:inline">الإدارة</span>
                  </button>
                )}
                {(currentRole === 'admin' || permissions.canReports) && (
                  <button
                    onClick={() => setReportsOpen(true)}
                    style={{ background: GLASS_SOFT, color: TEXT_MUTED, border: `1px solid ${GLASS_BORDER}` }}
                    className="flex items-center gap-1.5 font-bold text-sm px-3 py-2.5 rounded-full"
                    aria-label="التقارير"
                  >
                    <Printer size={16} />
                    <span className="hidden sm:inline">تقارير</span>
                  </button>
                )}
                {permissions.canAdd && (
                  <button
                    onClick={openNew}
                    style={{ background: ACCENT, color: ACCENT_TEXT_ON, boxShadow: '0 0 18px rgba(87,182,255,0.4)' }}
                    className="flex items-center gap-1.5 font-bold text-sm px-4 py-2.5 rounded-full hover:opacity-90 transition"
                  >
                    <Plus size={18} />
                    <span className="hidden sm:inline">طلب جديد</span>
                  </button>
                )}
                <button
                  onClick={handleLogout}
                  style={{ background: GLASS_SOFT, color: TEXT_MUTED, border: `1px solid ${GLASS_BORDER}` }}
                  className="flex items-center gap-1.5 font-bold text-sm px-3 py-2.5 rounded-full"
                  aria-label="تسجيل الخروج"
                >
                  <LogOut size={16} />
                  <span className="hidden sm:inline">خروج</span>
                </button>
              </div>
            </div>
            <div className="hero-line mt-5" style={{ height: 1, background: `linear-gradient(90deg, transparent, ${ACCENT}, transparent)`, opacity: 0.7 }} />
          </div>
        </header>

        <main className="max-w-4xl mx-auto px-5 sm:px-8 py-6">
          <IntroTicker />

          <div className="grid grid-cols-3 gap-3 mb-5">
            <StatCard label="إجمالي الطلبات" value={counts.total} color={TEXT} />
            <StatCard label="صدر أمر الشراء" value={counts.issued} color={ACCENT} />
            <StatCard label="بانتظار الأمر" value={counts.pending} color={PENDING} />
          </div>

          <div style={{ background: GLASS, border: `1px solid ${GLASS_BORDER}` }} className="glass rounded-2xl p-3 mb-4 flex flex-col sm:flex-row gap-3">
            <div className="relative flex-1">
              <Search size={16} style={{ color: TEXT_MUTED }} className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
              <input
                value={query}
                onChange={e => setQuery(e.target.value)}
                placeholder="ابحث برقم الطلب، رقم أمر الشراء، الجهة، أو المورّد"
                style={{ background: FIELD_BG, color: TEXT, border: `1px solid ${FIELD_BORDER}` }}
                className="w-full rounded-xl py-2.5 pr-9 pl-3 text-sm placeholder:text-slate-400"
              />
            </div>
            <div className="flex flex-wrap gap-2">
              <div className="relative">
                <FileStack size={14} style={{ color: TEXT_MUTED }} className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
                <select
                  value={categoryFilter}
                  onChange={e => setCategoryFilter(e.target.value)}
                  style={{ background: 'rgba(255,255,255,0.08)', color: TEXT, border: `1px solid ${FIELD_BORDER}` }}
                  className="filter-pill rounded-full pl-3 pr-9 py-2.5 text-sm font-medium"
                >
                  <option value="all">كل الأقسام</option>
                  {CATEGORIES.map(c => (
                    <option key={c} value={c}>{c}</option>
                  ))}
                </select>
              </div>
              <div className="relative">
                <Shield size={14} style={{ color: TEXT_MUTED }} className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none" />
                <select
                  value={statusFilter}
                  onChange={e => setStatusFilter(e.target.value)}
                  style={{ background: 'rgba(255,255,255,0.08)', color: TEXT, border: `1px solid ${FIELD_BORDER}` }}
                  className="filter-pill rounded-full pl-3 pr-9 py-2.5 text-sm font-medium"
                >
                  <option value="all">كل الحالات</option>
                  <option value="issued">صدر الأمر</option>
                  <option value="pending">لم يصدر</option>
                </select>
              </div>
              <button
                onClick={() => setSortDir(d => (d === 'desc' ? 'asc' : 'desc'))}
                style={{ background: 'rgba(255,255,255,0.08)', color: TEXT, border: `1px solid ${FIELD_BORDER}` }}
                className="filter-pill rounded-full px-4 py-2.5 text-sm font-medium flex items-center gap-1.5 whitespace-nowrap"
              >
                <ArrowUpDown size={15} style={{ color: ACCENT }} />
                {sortDir === 'desc' ? 'الأحدث أولاً' : 'الأقدم أولاً'}
              </button>
            </div>
          </div>

          {formOpen && (
            <OrderForm
              form={form}
              setForm={setForm}
              onSubmit={handleSubmit}
              onCancel={() => {
                setFormOpen(false);
                setForm(emptyForm);
                setEditingId(null);
                setError('');
                setInvalidFields([]);
              }}
              saving={saving}
              error={error}
              editing={!!editingId}
              invalidFields={invalidFields}
              shakeKey={shakeKey}
              canUpload={currentRole === 'admin' || permissions.canUpload}
            />
          )}

          <div className="glass rounded-2xl overflow-hidden" style={{ background: GLASS, border: `1px solid ${GLASS_BORDER}` }}>
            {!loaded ? (
              <div className="py-16 text-center" style={{ color: TEXT_MUTED }}>
                جارِ التحميل...
              </div>
            ) : filtered.length === 0 ? (
              <EmptyState hasOrders={orders.length > 0} onAdd={openNew} canEdit={permissions.canAdd} />
            ) : (
              filtered.map((order, i) => (
                <OrderRow
                  key={order.id}
                  order={order}
                  index={i}
                  highlighted={order.id === highlightId}
                  canEdit={currentRole === 'admin' || permissions.canEdit}
                  canDelete={currentRole === 'admin' || permissions.canDelete}
                  onView={() => openView(order)}
                  onEdit={() => openEdit(order)}
                  onDelete={() => handleDelete(order.id)}
                />
              ))
            )}
          </div>
        </main>

        <Toast message={toast} />
        </div>
        )}

        {viewingOrder && (
          <OrderDetailModal
            order={viewingOrder}
            canEdit={currentRole === 'admin' || permissions.canEdit}
            canDelete={currentRole === 'admin' || permissions.canDelete}
            onClose={() => setViewingOrder(null)}
            onEdit={() => openEdit(viewingOrder)}
            onDelete={() => handleDelete(viewingOrder.id)}
          />
        )}

        {adminOpen && currentRole === 'admin' && (
          <AdminPanel
            viewers={viewers}
            onClose={() => setAdminOpen(false)}
            onAdd={addViewerAccount}
            onDelete={deleteViewerAccount}
            onUpdatePermissions={updateViewerPermissions}
            onChangeViewerPassword={changeViewerPassword}
            onChangeAdminPassword={changeAdminPassword}
            adminUsername={adminUsername}
          />
        )}

        {reportsOpen && currentRole === 'admin' && (
          <ReportsModal orders={orders} onClose={() => setReportsOpen(false)} />
        )}

        <IdleOverlay active={idle && appStage !== 'splash'} />
      </div>
    </div>
  );
}

function Toast({ message }) {
  if (!message) return null;
  return (
    <div
      key={message}
      className="toast-in glass"
      style={{
        position: 'fixed',
        top: 18,
        left: '50%',
        background: GLASS_STRONG,
        color: TEXT,
        border: `1px solid ${GLASS_BORDER}`,
        padding: '10px 20px',
        borderRadius: 999,
        fontSize: 13,
        fontWeight: 700,
        boxShadow: '0 8px 28px rgba(0,0,0,0.4), 0 0 20px rgba(87,182,255,0.25)',
        zIndex: 50,
        display: 'flex',
        alignItems: 'center',
        gap: 8,
      }}
    >
      <CheckCircle2 size={16} color={ACCENT} />
      {message}
    </div>
  );
}

function IntroTicker() {
  const slides = [
    () => (
      <>
        <p style={{ color: TEXT, fontFamily: "'Cairo', sans-serif" }} className="text-sm sm:text-base font-bold">
          الإدارة العامة لتقنية المعلومات
        </p>
        <p style={{ color: TEXT_MUTED }} className="text-xs sm:text-sm mt-0.5">
          قسم المخازن الفنية
        </p>
      </>
    ),
    () => (
      <p style={{ color: TEXT_MUTED }} className="text-xs sm:text-sm leading-relaxed">
        هذا السجل يساعدك على متابعة كل طلب تسويه: تحفظه برقمه وقسمه ومقدّمه، تتابع هل صدر أمر الشراء أو لا، وترفق أي مستندات تخصّه — عشان ترجع لأي طلب بسهولة وقت ما تحتاجه.
      </p>
    ),
  ];
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const t = setInterval(() => setIndex(i => (i + 1) % slides.length), 4500);
    return () => clearInterval(t);
  }, []);

  const fromRight = index % 2 === 0;
  const Slide = slides[index];

  return (
    <div style={{ overflow: 'hidden' }} className="mb-5">
      <div key={index} className={fromRight ? 'intro-from-right' : 'intro-from-left'}>
        <Slide />
      </div>
    </div>
  );
}

