function AttachmentsField({ form, setForm, canUpload = true }) {
  const [fileError, setFileError] = useState('');
  const inputRef = React.useRef(null);

  function handleFiles(fileList) {
    const files = Array.from(fileList || []);
    if (!files.length) return;
    setFileError('');
    let runningTotal = (form.attachments || []).reduce((s, a) => s + (a.size || 0), 0);

    files.forEach(file => {
      if (runningTotal + file.size > MAX_ATTACH_BYTES) {
        setFileError(`تجاوزت الحد الأقصى لحجم المرفقات لهذا الطلب (${formatBytes(MAX_ATTACH_BYTES)} تقريبًا)`);
        return;
      }
      runningTotal += file.size;
      const reader = new FileReader();
      reader.onload = () => {
        const att = { id: uid(), name: file.name, type: file.type || 'application/octet-stream', size: file.size, dataUrl: reader.result };
        setForm(f => ({ ...f, attachments: [...(f.attachments || []), att] }));
      };
      reader.onerror = () => setFileError('تعذّرت قراءة أحد الملفات، حاول مرة أخرى');
      reader.readAsDataURL(file);
    });
  }

  function removeAttachment(id) {
    setForm(f => ({ ...f, attachments: (f.attachments || []).filter(a => a.id !== id) }));
  }

  return (
    <div>
      <span style={{ color: TEXT_MUTED }} className="text-xs font-medium mb-1 block">
        المرفقات والمستندات
      </span>

      {(form.attachments || []).length > 0 && (
        <div className="flex flex-wrap gap-2 mb-2">
          {form.attachments.map(a => (
            <span
              key={a.id}
              style={{ background: FIELD_BG, border: `1px solid ${FIELD_BORDER}`, color: TEXT }}
              className="flex items-center gap-1.5 rounded-full py-1 px-2"
            >
              <Paperclip size={12} style={{ color: TEXT_MUTED }} />
              <span style={{ fontSize: 12, maxWidth: 140 }} className="whitespace-nowrap overflow-hidden text-ellipsis">
                {a.name}
              </span>
              <button
                type="button"
                onClick={() => removeAttachment(a.id)}
                style={{ color: TEXT_MUTED }}
                aria-label={`إزالة ${a.name}`}
              >
                <X size={12} />
              </button>
            </span>
          ))}
        </div>
      )}

      {canUpload && (
        <button
          type="button"
          onClick={() => inputRef.current && inputRef.current.click()}
          style={{ background: FIELD_BG, border: `1px dashed ${FIELD_BORDER}`, color: TEXT_MUTED }}
          className="w-full rounded-lg py-2.5 text-sm flex items-center justify-center gap-1.5"
        >
          <Paperclip size={14} />
          إرفاق ملف أو مستند
        </button>
      )}
      <input
        ref={inputRef}
        type="file"
        multiple
        className="hidden"
        onChange={e => {
          handleFiles(e.target.files);
          e.target.value = '';
        }}
      />

      {fileError && (
        <p style={{ color: REQUIRED_RED }} className="text-xs mt-1.5">
          {fileError}
        </p>
      )}
    </div>
  );
}

