function IdleOverlay({ active }) {
  const [verseIndex, setVerseIndex] = useState(0);

  useEffect(() => {
    if (!active) {
      setVerseIndex(0);
      return;
    }
    const t = setInterval(() => setVerseIndex(i => (i + 1) % VERSES.length), VERSE_INTERVAL_MS);
    return () => clearInterval(t);
  }, [active]);

  if (!active) return null;
  const verse = VERSES[verseIndex];

  return (
    <div
      className="idle-overlay"
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 100,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 32,
        textAlign: 'center',
      }}
    >
      <div
        style={{
          position: 'absolute',
          inset: 0,
          backdropFilter: 'blur(24px)',
          WebkitBackdropFilter: 'blur(24px)',
          background: 'rgba(4,8,14,0.6)',
        }}
      />
      <div key={verseIndex} className="verse-in" style={{ position: 'relative', maxWidth: 560 }}>
        <p
          style={{ fontFamily: "'Cairo', sans-serif", color: TEXT, fontSize: 26, lineHeight: 1.9, fontWeight: 700 }}
        >
          {verse.text}
        </p>
        <p style={{ color: ACCENT, fontSize: 14, marginTop: 18, fontWeight: 600 }}>{verse.ref}</p>
      </div>
    </div>
  );
}

function Splash() {
  const [leaving, setLeaving] = useState(false);
  const word = 'Welcome to Store';
  const chars = word.split('');
  const mid = Math.ceil(chars.length / 2);
  const assembleMs = 70;
  const subDelay = chars.length * assembleMs + 300;

  useEffect(() => {
    const t = setTimeout(() => setLeaving(true), SPLASH_MIN_MS - 550);
    return () => clearTimeout(t);
  }, []);
  return (
    <div
      className={leaving ? 'splash-out' : ''}
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 40,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        textAlign: 'center',
        padding: 24,
      }}
    >
      <div
        style={{ background: ACCENT, color: ACCENT_TEXT_ON, boxShadow: '0 0 30px rgba(87,182,255,0.55)' }}
        className="splash-text w-16 h-16 rounded-full flex items-center justify-center mb-5"
      >
        <Store size={30} />
      </div>
      <h1
        dir="ltr"
        style={{ fontFamily: "'Cairo', sans-serif", color: TEXT, letterSpacing: 0.5, whiteSpace: 'pre' }}
        className="text-3xl sm:text-4xl font-extrabold flex"
      >
        {chars.map((ch, i) => {
          const fromRight = i < mid;
          return (
            <span
              key={i}
              style={{
                display: 'inline-block',
                animation: `${fromRight ? 'charFromRight' : 'charFromLeft'} 0.55s cubic-bezier(0.22, 1, 0.36, 1) ${i * assembleMs}ms both`,
              }}
            >
              {ch === ' ' ? '\u00A0' : ch}
            </span>
          );
        })}
      </h1>
      <div
        className="splash-sub mt-4"
        style={{
          width: 120,
          height: 1,
          background: `linear-gradient(90deg, transparent, ${ACCENT}, transparent)`,
          animationDelay: `${subDelay}ms`,
        }}
      />
      <p
        style={{ color: TEXT_MUTED, fontFamily: "'Tajawal', sans-serif", animationDelay: `${subDelay + 150}ms` }}
        className="splash-sub mt-4 text-sm sm:text-base"
      >
        سجل الطلبات
      </p>
    </div>
  );
}

